    const Subprocess::IO& err,
    const Option<flags::FlagsBase>& flags = None(),
    const Option<std::map<std::string, std::string> >& environment = None(),
    const Option<lambda::function<int()> >& setup = None());
{noformat} $acceptance criteria:$

